// parser-loader.wasm.js — Drop-in replacement for parser-loader.js
// Uses web-tree-sitter WASM instead of native tree-sitter .node addons.
//
// Swap: rename to parser-loader.js when using bun build --compile
//
// Interface is IDENTICAL to the original:
//   resolveLanguageKey(language, filePath?) => string
//   isLanguageAvailable(language, filePath?) => boolean
//   getLanguageGrammar(language, filePath?) => unknown (Language)
//   loadParser() => Promise<Parser>           (web-tree-sitter Parser)
//   loadLanguage(language, filePath?) => Promise<void>
//   createParserForLanguage(language, filePath?) => Promise<Parser>

import { Parser, Language } from 'web-tree-sitter';
import { createRequire } from 'node:module';
import { SupportedLanguages } from '../../_shared/index.js';
import { logger } from '../logger.js';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const _require = createRequire(import.meta.url);
const __dirname = path.dirname(fileURLToPath(import.meta.url));

// ─── Inline embedded WASM base64 strings ────────────────────────────────────
// These are auto-generated by scripts/embed-wasm.mjs.
// For bun build --compile, these get inlined at build time via a build plugin.
const RUNTIME_WASM_B64 = null; // Set by build plugin or runtime loader
const EMBEDDED_WASM = {};      // Populated at build time by embed-wasm.mjs

const WASM_VAR_MAP = {
  'tree-sitter-javascript.wasm': 'tree_sitter_javascript',
  'tree-sitter-typescript.wasm': 'tree_sitter_typescript',
  'tree-sitter-tsx.wasm': 'tree_sitter_tsx',
  'tree-sitter-python.wasm': 'tree_sitter_python',
  'tree-sitter-java.wasm': 'tree_sitter_java',
  'tree-sitter-c_sharp.wasm': 'tree_sitter_c_sharp',
  'tree-sitter-cpp.wasm': 'tree_sitter_cpp',
  'tree-sitter-go.wasm': 'tree_sitter_go',
  'tree-sitter-rust.wasm': 'tree_sitter_rust',
  'tree-sitter-php_only.wasm': 'tree_sitter_php_only',
  'tree-sitter-ruby.wasm': 'tree_sitter_ruby',
  'web-tree-sitter.wasm': 'web_tree_sitter',
};

// ─── Native addon fallback (for grammars without WASM) ──────────────────────

const ISSUES_URL = 'https://github.com/abhigyanpatwari/GitNexus/issues';

const G = SupportedLanguages;

const SOURCES = {
  [G.JavaScript]:     { wasmKey: 'tree-sitter-javascript', wasmFile: 'tree-sitter-javascript.wasm', note: 'JavaScript' },
  [G.TypeScript]:     { wasmKey: 'tree-sitter-typescript', wasmFile: 'tree-sitter-typescript.wasm', note: 'TypeScript' },
  [`${G.TypeScript}:tsx`]: { wasmKey: 'tree-sitter-typescript', wasmFile: 'tree-sitter-tsx.wasm', note: 'TSX' },
  [G.Python]:         { wasmKey: 'tree-sitter-python', wasmFile: 'tree-sitter-python.wasm', note: 'Python' },
  [G.Java]:           { wasmKey: 'tree-sitter-java', wasmFile: 'tree-sitter-java.wasm', note: 'Java' },
  [G.CSharp]:         { wasmKey: 'tree-sitter-c-sharp', wasmFile: 'tree-sitter-c_sharp.wasm', note: 'C#' },
  [G.CPlusPlus]:       { wasmKey: 'tree-sitter-cpp', wasmFile: 'tree-sitter-cpp.wasm', note: 'C++' },
  [G.Go]:             { wasmKey: 'tree-sitter-go', wasmFile: 'tree-sitter-go.wasm', note: 'Go' },
  [G.Rust]:           { wasmKey: 'tree-sitter-rust', wasmFile: 'tree-sitter-rust.wasm', note: 'Rust' },
  [G.PHP]:            { wasmKey: 'tree-sitter-php', wasmFile: 'tree-sitter-php_only.wasm', note: 'PHP' },
  [G.Ruby]:           { wasmKey: 'tree-sitter-ruby', wasmFile: 'tree-sitter-ruby.wasm', note: 'Ruby' },
  [G.Vue]:            { wasmKey: 'tree-sitter-typescript', wasmFile: 'tree-sitter-typescript.wasm', note: 'Vue (piggybacks on TS)' },

  [G.C]: {
    native: true,
    load: () => _require('tree-sitter-c'),
    optional: true,
    severity: 'error',
    note: 'C',
    unavailableNote:
      'C parsing disabled: `tree-sitter-c` (v0.21.4) does not ship a .wasm file. ' +
      'Upgrade to >=0.23 or build WASM manually with `tree-sitter build --wasm`.',
  },
  [G.Swift]: {
    native: true,
    load: () => _require('tree-sitter-swift'),
    optional: true,
    note: 'Swift',
    unavailableNote:
      'Swift parsing disabled: vendored `tree-sitter-swift` does not ship a .wasm file.',
  },
  [G.Dart]: {
    native: true,
    load: () => _require('tree-sitter-dart'),
    optional: true,
    note: 'Dart',
    unavailableNote:
      'Dart parsing disabled: vendored `tree-sitter-dart` does not ship a .wasm file.',
  },
  [G.Kotlin]: {
    native: true,
    load: () => _require('tree-sitter-kotlin'),
    optional: true,
    note: 'Kotlin',
    unavailableNote:
      'Kotlin parsing disabled: `tree-sitter-kotlin` does not ship a .wasm file.',
  },
};

// ─── Runtime state ──────────────────────────────────────────────────────────

let initialized = false;
const loadResultCache = new Map();
const languageCache = new Map();
const logged = new Set();
let sharedParser = null;

// ─── Embedded WASM file resolution ──────────────────────────────────────────

const WASM_DIR = path.resolve(__dirname, 'wasm');

function getEmbeddedWasmPath(wasmFile) {
  const varName = WASM_VAR_MAP[wasmFile];
  if (!varName) return null;
  return path.join(WASM_DIR, `${varName}.js`);
}

function embeddedWasmFileExists(wasmFile) {
  const p = getEmbeddedWasmPath(wasmFile);
  return p ? fs.existsSync(p) : false;
}

async function importEmbeddedWasm(wasmFile) {
  const p = getEmbeddedWasmPath(wasmFile);
  if (!p || !fs.existsSync(p)) return null;
  try {
    const mod = await import(`file://${p.replace(/\\/g, '/')}`);
    if (mod && mod.default) {
      return Buffer.from(mod.default, 'base64');
    }
  } catch { /* fall through */ }
  return null;
}

function getPackageRoot(pkgName) {
  const mainPath = path.dirname(_require.resolve(pkgName + '/package.json'));
  let dir = mainPath;
  while (dir) {
    const pj = path.join(dir, 'package.json');
    if (fs.existsSync(pj)) {
      const pkg = JSON.parse(fs.readFileSync(pj, 'utf-8'));
      if (pkg.name === pkgName) return dir;
    }
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return mainPath;
}

// Synchronous check: does the wasm file exist in any embedded or filesystem location?
function checkWasmFileSync(config) {
  // 1. Embedded (set by build plugin)
  const embedded = EMBEDDED_WASM[config.wasmKey]?.[config.wasmFile];
  if (embedded) return true;
  // 2. Generated dist files
  if (embeddedWasmFileExists(config.wasmFile)) return true;
  // 3. node_modules filesystem
  try {
    const pkgRoot = getPackageRoot(config.wasmKey);
    const wasmPath = path.join(pkgRoot, config.wasmFile);
    return fs.existsSync(wasmPath);
  } catch { /* fall through */ }
  return false;
}

// ─── Init: lazy Parser init with WASM runtime ───────────────────────────────

async function ensureInit() {
  if (initialized) return;
  if (RUNTIME_WASM_B64) {
    const wasmBytes = Buffer.from(RUNTIME_WASM_B64, 'base64');
    await Parser.init({ wasmBinary: wasmBytes });
  } else {
    try {
      const embedded = await importEmbeddedWasm('web-tree-sitter.wasm');
      if (embedded) {
        await Parser.init({ wasmBinary: embedded });
        initialized = true;
        return;
      }
    } catch { /* fall through */ }
    try {
      const wtsPath = path.dirname(_require.resolve('web-tree-sitter'));
      const wasmPath = path.join(wtsPath, 'web-tree-sitter.wasm');
      if (fs.existsSync(wasmPath)) {
        await Parser.init({ wasmBinary: fs.readFileSync(wasmPath) });
      } else {
        await Parser.init();
      }
    } catch {
      await Parser.init();
    }
  }
  initialized = true;
}

// ─── Async WASM resolution ─────────────────────────────────────────────────

async function resolveWasmBytes(config) {
  const embedded = EMBEDDED_WASM[config.wasmKey]?.[config.wasmFile];
  if (embedded) return Buffer.from(embedded, 'base64');
  const imported = await importEmbeddedWasm(config.wasmFile);
  if (imported) return imported;
  try {
    const pkgRoot = getPackageRoot(config.wasmKey);
    const wasmPath = path.join(pkgRoot, config.wasmFile);
    if (fs.existsSync(wasmPath)) return fs.readFileSync(wasmPath);
  } catch { /* fall through */ }
  return null;
}

// ─── Logging ────────────────────────────────────────────────────────────────

const logFailure = (key, result) => {
  if (result.ok === true) return;
  if (logged.has(key)) return;
  logged.add(key);
  const message = `[gitnexus] ${result.note} (${result.error.message})`;
  if (result.severity === 'error') logger.error(message);
  else logger.warn(message);
};

// ─── Eager synchronous availability check ───────────────────────────────────
// Matches the original parser-loader's sync behavior: isLanguageAvailable
// eagerly attempts to resolve the grammar and caches the result.

function checkGrammarAvailable(key) {
  const source = SOURCES[key];
  if (!source) return false;

  // Native grammars: load synchronously via _require
  if (source.native) {
    let result;
    try {
      result = { ok: true, grammar: source.load() };
    } catch (err) {
      const fatal = !source.optional;
      result = {
        ok: false, error: err, note: source.unavailableNote,
        fatal, severity: source.severity ?? (fatal ? 'error' : 'warn'),
      };
    }
    loadResultCache.set(key, result);
    if (result.ok === false) logFailure(key, result);
    return result.ok === true;
  }

  // WASM grammars: check if WASM file can be found on disk
  // (actual Language.load() happens async later)
  const available = checkWasmFileSync(source);
  if (available) {
    // Mark as available-but-not-loaded (grammar will be loaded later)
    loadResultCache.set(key, { ok: true, grammar: null });
    return true;
  }
  return false;
}

// ─── Exported interface ─────────────────────────────────────────────────────

export const resolveLanguageKey = (language, filePath) =>
  language === SupportedLanguages.TypeScript && filePath?.endsWith('.tsx')
    ? `${language}:tsx`
    : language;

export const isLanguageAvailable = (language, filePath) => {
  const key = resolveLanguageKey(language, filePath);
  const cached = loadResultCache.get(key);
  if (cached) return cached.ok === true;
  return checkGrammarAvailable(key);
};

export const getLanguageGrammar = (language, filePath) => {
  const key = resolveLanguageKey(language, filePath);
  const result = loadResultCache.get(key);

  // If result says OK but grammar is null (WASM that's known-available
  // but not yet loaded via Language.load()), we can't return it yet.
  if (result?.ok === true) {
    if (result.grammar !== null) return result.grammar;
    // WASM grammar marked available but not loaded — caller needs
    // loadLanguage()/createParserForLanguage() first.
    throw new Error(
      `Language "${language}" not loaded yet. Call loadLanguage() first.`,
    );
  }

  // Check if the key exists at all
  const source = SOURCES[key];
  if (!source) {
    throw new Error(`Unsupported language: ${language}`);
  }

  // Fatal errors throw the original error
  if (result?.fatal) throw result.error;
  throw new Error(`Unsupported language: ${language}`);
};

export const loadParser = async () => {
  await ensureInit();
  return (sharedParser ??= new Parser());
};

async function loadGrammarAsync(key) {
  const cached = loadResultCache.get(key);
  if (cached?.['_loading']) return cached._promise;
  if (cached?.ok === true && cached.grammar !== null) return cached;

  const source = SOURCES[key];
  if (!source) {
    const result = { ok: false, error: new Error(`Unsupported language: ${key}`), note: `No grammar registered for language key \`${key}\`.`, fatal: true, severity: 'error' };
    loadResultCache.set(key, result);
    return result;
  }

  // Native: already handled by sync checkGrammarAvailable
  if (source.native) {
    const r = loadResultCache.get(key);
    if (r) return r;
    return checkGrammarAvailable(key) ? loadResultCache.get(key) : { ok: false, error: new Error(`Native grammar unavailable: ${key}`), note: source.unavailableNote, fatal: true, severity: 'error' };
  }

  // WASM: async load
  const promise = (async () => {
    try {
      await ensureInit();
      const wasmBytes = await resolveWasmBytes(source);
      if (!wasmBytes) {
        const result = { ok: false, error: new Error(`WASM file not found for ${key}`), note: `${source.note} grammar WASM file not found.`, fatal: false, severity: 'warn' };
        loadResultCache.set(key, result);
        logFailure(key, result);
        return result;
      }
      const language = await Language.load(wasmBytes);
      languageCache.set(key, language);
      const result = { ok: true, grammar: language };
      loadResultCache.set(key, result);
      return result;
    } catch (err) {
      const result = { ok: false, error: err, note: `Failed to load WASM grammar for ${key}: ${err.message}`, fatal: true, severity: 'error' };
      loadResultCache.set(key, result);
      logFailure(key, result);
      return result;
    }
  })();

  loadResultCache.set(key, { _loading: true, _promise: promise });
  const result = await promise;
  return result;
}

export const loadLanguage = async (language, filePath) => {
  const key = resolveLanguageKey(language, filePath);

  // If grammar is marked as available but not loaded, trigger async load
  const cached = loadResultCache.get(key);
  if (cached?.ok === true && cached.grammar === null) {
    await loadGrammarAsync(key);
  } else if (!cached || cached._loading) {
    await loadGrammarAsync(key);
  }

  const parser = await loadParser();
  const grammar = getLanguageGrammar(language, filePath);
  parser.setLanguage(grammar);
};

export const createParserForLanguage = async (language, filePath) => {
  await ensureInit();
  const key = resolveLanguageKey(language, filePath);

  const cached = loadResultCache.get(key);
  if (!cached || cached._loading) {
    await loadGrammarAsync(key);
  } else if (cached.ok === true && cached.grammar === null) {
    await loadGrammarAsync(key);
  }

  const parser = new Parser();
  const grammar = getLanguageGrammar(language, filePath);
  parser.setLanguage(grammar);
  return parser;
};
